use axum::{http::header, response::IntoResponse};
use maud::{html, Markup};

// Hosts the Google tag beacons need; headers.rs puts them in connect-src and img-src only. Set both to "" without a Google tag.
pub const BEACON_CONNECT_SRC: &str = "https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com https://www.googletagmanager.com";
pub const BEACON_IMG_SRC: &str = "https://www.google-analytics.com";

pub fn banner(nonce: &str) -> Markup {
    html! {
        div id="consent-banner" role="dialog" aria-label="Cookie consent" hidden {
            p { "We use analytics cookies only if you accept. " a href="/privacy" { "Privacy notice" } }
            button type="button" class="consent-btn" data-consent="granted" { "Accept all" }
            button type="button" class="consent-btn" data-consent="denied" { "Reject all" }
        }
        button type="button" id="consent-reopen" class="consent-link" hidden { "Cookie settings" }
        // PRV-001: external script carrying the CSP nonce; consent.js reads it from document.currentScript
        script defer src="/consent.js" nonce=(nonce) {}
    }
}

pub async fn script() -> impl IntoResponse {
    (
        [(header::CONTENT_TYPE, "text/javascript; charset=utf-8"), (header::CACHE_CONTROL, "no-cache")],
        include_str!("consent.js"),
    )
}

