// src/layout.rs - the site chrome every page (including error pages) renders inside.
// UX-005: keeps a <nav> landmark and an <a href="/"> link on every page, error pages included.
use crate::consent;
use maud::{html, Markup, DOCTYPE};

pub fn page(nonce: &str, title: &str, noindex: bool, body: Markup) -> Markup {
    html! {
        (DOCTYPE)
        html lang="en" {
            head {
                meta charset="utf-8";
                meta name="viewport" content="width=device-width, initial-scale=1";
                title { (title) }
                @if noindex { meta name="robots" content="noindex"; } // UX-005: 404/410 pages are not indexed
                link rel="stylesheet" href="/assets/site.0a1b2c3d.css"; // fingerprinted file from your build
            }
            body {
                header { nav aria-label="Main" { a href="/" { "Home" } " " a href="/contact" { "Contact" } } }
                main { (body) }
                footer { a href="/privacy" { "Privacy notice" } }
                (consent::banner(nonce))
            }
        }
    }
}

