use std::{any::Any, time::Duration};

use axum::{
    extract::{Path, Request, State},
    http::{StatusCode, Uri},
    middleware::Next,
    response::{Html, IntoResponse, Response},
    Extension,
};
use maud::html;

use crate::{headers::Nonce, layout, AppState};

#[derive(Clone, Copy, Debug)]
pub enum AppError {
    NotFound,
    Gone,
    Unavailable,
    BadGateway,
    Internal,
}

impl AppError {
    fn status(self) -> StatusCode {
        match self {
            Self::NotFound => StatusCode::NOT_FOUND,
            Self::Gone => StatusCode::GONE,
            Self::Unavailable => StatusCode::SERVICE_UNAVAILABLE,
            Self::BadGateway => StatusCode::BAD_GATEWAY,
            Self::Internal => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
    fn heading(self) -> &'static str {
        match self {
            Self::NotFound => "Page not found",
            Self::Gone => "This page has been removed",
            Self::Unavailable | Self::BadGateway => "Temporarily unavailable",
            Self::Internal => "Something went wrong",
        }
    }
}

impl IntoResponse for AppError {
    // Bare status plus a marker; the middleware below renders the page (it knows the CSP nonce).
    fn into_response(self) -> Response {
        let mut res = self.status().into_response();
        res.extensions_mut().insert(self);
        res
    }
}

pub async fn render_error_pages(req: Request, next: Next) -> Response {
    let nonce = req.extensions().get::<Nonce>().map(|n| n.0.clone()).unwrap_or_default();
    let res = next.run(req).await;
    let Some(err) = res.extensions().get::<AppError>().copied() else { return res };
    let body = html! { h1 { (err.heading()) } p { a href="/" { "Back to the home page" } } };
    // RTE-004/007: real status, never a 200 shell; 404/410 carry noindex (UX-005).
    let noindex = matches!(err, AppError::NotFound | AppError::Gone);
    (err.status(), Html(layout::page(&nonce, err.heading(), noindex, body).into_string())).into_response()
}

const RETIRED: &[&str] = &["/old-pricing"]; // retired paths with no successor answer 410

pub async fn fallback(uri: Uri) -> AppError {
    if RETIRED.contains(&uri.path()) { AppError::Gone } else { AppError::NotFound }
}

/// SEC-007: a panic becomes a plain 500 page; the payload is logged, never sent.
pub fn panic_response(payload: Box<dyn Any + Send + 'static>) -> Response {
    let detail = payload.downcast_ref::<&str>().copied().unwrap_or("panic");
    tracing::error!("handler panicked: {detail}");
    AppError::Internal.into_response()
}

/// Example dynamic route: validate the param before any lookup (RTE-006), DB down is 503 not 404 (RTE-007).
pub async fn post(
    State(app): State<AppState>,
    Extension(nonce): Extension<Nonce>,
    Path(slug): Path<String>,
) -> Result<Html<String>, AppError> {
    if slug.len() > 64 || !slug.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-') {
        return Err(AppError::NotFound);
    }
    let query = sqlx::query_scalar::<_, String>("SELECT title FROM posts WHERE slug = $1")
        .bind(&slug)
        .fetch_optional(&app.db);
    let title = match tokio::time::timeout(Duration::from_secs(3), query).await {
        Ok(Ok(Some(title))) => title,
        Ok(Ok(None)) => return Err(AppError::NotFound), // decided before any bytes are sent
        Ok(Err(e)) => { tracing::error!("db: {e}"); return Err(AppError::Unavailable) }
        Err(_) => return Err(AppError::Unavailable),
    };
    Ok(Html(layout::page(&nonce.0, &title, false, html! { h1 { (title) } }).into_string()))
}

