use serde::{Deserialize, Serialize};
use tower_http::csrf::CsrfLayer;

use crate::{errors::AppError, headers::Nonce, layout, AppState};

#[derive(Deserialize, Serialize)]
pub struct Contact {
    name: String,
    email: String,
    message: String,
    #[serde(default, skip_serializing)]
    website: String, // honeypot, see the form below
}

/// SEC-024: tower-http checks Sec-Fetch-Site and Origin on every non-GET and answers 403 cross-site.
/// Needs the proxy to pass Host and Origin through unchanged.
pub fn csrf_layer(site_url: &str) -> CsrfLayer {
    CsrfLayer::new().add_trusted_origin(site_url).expect("SITE_URL must be an origin like https://example.com")
}

/// SEC-054: in-memory, per process. Behind a proxy use the client IP header your proxy sets, not the socket address.
#[derive(Default)]
pub struct RateLimiter(Mutex<HashMap<IpAddr, VecDeque<Instant>>>);

impl RateLimiter {
    pub fn allow(&self, ip: IpAddr) -> bool {
        const MAX: usize = 5;
        const WINDOW: Duration = Duration::from_secs(600);
        let now = Instant::now();
        let mut map = self.0.lock().unwrap_or_else(|e| e.into_inner());
        map.retain(|_, hits| {
            while hits.front().is_some_and(|t| now.duration_since(*t) > WINDOW) { hits.pop_front(); }
            !hits.is_empty()
        });
        let hits = map.entry(ip).or_default();
        if hits.len() >= MAX { return false; }
        hits.push_back(now);
        true
    }
}

fn form_page(nonce: &str, error: Option<&str>) -> Markup {
    layout::page(nonce, "Contact", false, html! {
        h1 { "Contact us" }
        @if let Some(e) = error { p role="alert" { (e) } }
        form method="post" action="/contact" {
            label for="name" { "Name" }
            input id="name" name="name" type="text" autocomplete="name" required maxlength="100";
            label for="email" { "Email" }
            input id="email" name="email" type="email" autocomplete="email" required maxlength="254";
            label for="message" { "Message" }
            textarea id="message" name="message" required maxlength="5000" rows="6" {}
            // SEC-055 honeypot: not type=hidden, moved off-screen by CSS `.hp { position: absolute; left: -10000px; }`
            div class="hp" aria-hidden="true" {
                label for="website" { "Leave this field empty" }
                input id="website" name="website" type="text" tabindex="-1" autocomplete="off";
            }
            p { a href="/privacy" { "Privacy notice" } } // PRV-028: inside the form
            button type="submit" { "Send" }
        }
    })
}

fn reply(status: StatusCode, nonce: &str, msg: &str) -> Response {
    (status, Html(form_page(nonce, Some(msg)).into_string())).into_response()
}

pub async fn show(Extension(nonce): Extension<Nonce>) -> Html<String> {
    Html(form_page(&nonce.0, None).into_string())
}

pub async fn thanks(Extension(nonce): Extension<Nonce>) -> Html<String> {
    Html(layout::page(&nonce.0, "Thank you", true, html! { h1 { "Thank you" } p { "We received your message." } }).into_string())
}

pub async fn submit(
    State(app): State<AppState>,
    ConnectInfo(addr): ConnectInfo<SocketAddr>,
    Extension(nonce): Extension<Nonce>,
    Form(f): Form<Contact>,
) -> Result<Redirect, Response> {
    if !app.limiter.allow(addr.ip()) {
        let mut res = reply(StatusCode::TOO_MANY_REQUESTS, &nonce.0, "Too many messages. Please try again later.");
        res.headers_mut().insert(header::RETRY_AFTER, "600".parse().expect("static"));
        return Err(res);
    }
    if !f.website.is_empty() {
        return Ok(Redirect::to("/contact/thanks")); // bot: same answer as success, no side effect
    }
    let (name, email, message) = (f.name.trim(), f.email.trim(), f.message.trim());
    let valid = (1..=100).contains(&name.chars().count())
        && email.len() <= 254 && email.contains('@') && !email.contains(char::is_whitespace)
        && (1..=5000).contains(&message.chars().count());
    if !valid {
        return Err(reply(StatusCode::UNPROCESSABLE_ENTITY, &nonce.0, "Please check the fields and try again."));
    }
    // RES-008: replace this one call with your real destination (SMTP or provider API, CRM, database insert).
    // Success is shown only when it succeeds; any failure is a 502 page.
    let delivered = match app.cfg.webhook_url.as_deref() {
        Some(url) => app.http.post(url).json(&f).send().await.and_then(|r| r.error_for_status()).is_ok(),
        None => false, // FORM_WEBHOOK_URL not configured: never pretend it was sent
    };
    if !delivered {
        tracing::error!("contact delivery failed");
        return Err(AppError::BadGateway.into_response());
    }
    Ok(Redirect::to("/contact/thanks")) // 303 so a reload does not resubmit
}

