pub struct Config {
    pub production: bool, // true only when DEPLOY_ENV=production
    pub site_url: String, // https://example.com, no trailing slash
    pub webhook_url: Option<String>,
}

#[derive(Clone)]
pub struct AppState {
    pub db: PgPool,
    pub http: reqwest::Client,
    pub cfg: Arc<Config>,
    pub limiter: Arc<form::RateLimiter>,
}

async fn home(Extension(nonce): Extension<headers::Nonce>) -> Html<String> {
