#[tokio::main]
async fn main() {
    tracing_subscriber::fmt::init();
    let cfg = Config {
        production: env::var("DEPLOY_ENV").is_ok_and(|v| v == "production"),
        site_url: env::var("SITE_URL").unwrap_or_else(|_| "http://localhost:3000".into()).trim_end_matches('/').to_string(),
        webhook_url: env::var("FORM_WEBHOOK_URL").ok(),
    };
    let state = AppState {
        db: PgPoolOptions::new()
            .acquire_timeout(Duration::from_secs(2))
            .connect_lazy(&env::var("DATABASE_URL").expect("DATABASE_URL"))
            .expect("DATABASE_URL is not a valid connection string"),
        http: reqwest::Client::builder().timeout(Duration::from_secs(8)).build().expect("http client"),
        cfg: Arc::new(cfg),
        limiter: Arc::default(),
    };

    let app = Router::new()
        .route("/", get(home))
        .route("/posts/{slug}", get(errors::post))
        .route("/contact", get(form::show).post(form::submit).layer(DefaultBodyLimit::max(16 * 1024)))
        .route("/contact/thanks", get(form::thanks))
        .route("/consent.js", get(consent::script))
        .route("/api/health", get(health::health))
        .route("/robots.txt", get(seo::robots))
        .route("/sitemap.xml", get(seo::sitemap))
        .nest_service("/assets", ServeDir::new("assets").not_found_service(errors::fallback.into_service()))
        .fallback(errors::fallback)
        // Layers run bottom to top on the request: the last one added is the outermost.
        .layer(CatchPanicLayer::custom(errors::panic_response))
        .layer(form::csrf_layer(&state.cfg.site_url))
        .layer(middleware::from_fn(errors::render_error_pages));
    let app = headers::with_static_headers(app)
        .layer(middleware::from_fn_with_state(state.clone(), seo::noindex_outside_production))
        .layer(middleware::from_fn(headers::security_headers))
        .layer(TraceLayer::new_for_http())
        .with_state(state);

    let listener = tokio::net::TcpListener::bind("0.0.0.0:3000").await.expect("bind");
    axum::serve(listener, app.into_make_service_with_connect_info::<SocketAddr>()).await.expect("serve");
}

