// src/headers.rs - wire in main.rs: .layer(middleware::from_fn(headers::security_headers))
use axum::{
    extract::Request,
    http::{header, HeaderName, HeaderValue},
    middleware::Next,
    response::Response,
    Router,
};
use base64::{engine::general_purpose::STANDARD, Engine as _};
use tower_http::set_header::SetResponseHeaderLayer;

use crate::consent::{BEACON_CONNECT_SRC, BEACON_IMG_SRC};

/// Per-request CSP nonce; handlers read it with `Extension<Nonce>` and put it on their <script> tags.
#[derive(Clone)]
pub struct Nonce(pub String);

// SEC-010/SEC-075: nonce + 'strict-dynamic', no 'unsafe-inline' in script-src, frame-ancestors present.
// The analytics beacon hosts come from consent.rs and appear only in connect-src/img-src, never in script-src.
const CSP: &str = "default-src 'self'; script-src 'self' 'nonce-{NONCE}' 'strict-dynamic'; \
style-src 'self' 'nonce-{NONCE}'; img-src 'self' data: {IMG}; font-src 'self'; connect-src 'self' {CONNECT}; \
object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none'; upgrade-insecure-requests";

pub async fn security_headers(mut req: Request, next: Next) -> Response {
    let mut raw = [0u8; 16];
    getrandom::fill(&mut raw).expect("OS randomness unavailable"); // fresh nonce for every response
    let nonce = STANDARD.encode(raw);
    let is_asset = req.uri().path().starts_with("/assets/");
    req.extensions_mut().insert(Nonce(nonce.clone()));

    let mut res = next.run(req).await;
    let is_html = res
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| v.starts_with("text/html"));
    if is_html {
        let csp = CSP
            .replace("{NONCE}", &nonce)
            .replace("{IMG}", BEACON_IMG_SRC)
            .replace("{CONNECT}", BEACON_CONNECT_SRC);
        res.headers_mut()
            .insert(header::CONTENT_SECURITY_POLICY, HeaderValue::from_str(&csp).expect("ascii"));
        // PRF-008: `no-cache` so a CDN never replays one response (and its nonce) to other visitors.
        res.headers_mut()
            .entry(header::CACHE_CONTROL)
            .or_insert(HeaderValue::from_static("no-cache"));
    } else if is_asset && res.status().is_success() {
        // PRF-008: only for fingerprinted files (site.0a1b2c3d.css); never for unhashed names.
        res.headers_mut().insert(
            header::CACHE_CONTROL,
            HeaderValue::from_static("public, max-age=31536000, immutable"),
        );
    }
    res
}

/// Constant headers on every response (SEC-010). HSTS is ignored by browsers over plain http.
pub fn with_static_headers<S: Clone + Send + Sync + 'static>(router: Router<S>) -> Router<S> {
    let set = |name: &'static str, value: &'static str| {
        SetResponseHeaderLayer::overriding(HeaderName::from_static(name), HeaderValue::from_static(value))
    };
    router
        .layer(set("x-content-type-options", "nosniff"))
        .layer(set("referrer-policy", "strict-origin-when-cross-origin"))
        .layer(set("permissions-policy", "camera=(), microphone=(), geolocation=()"))
        .layer(set("strict-transport-security", "max-age=63072000; includeSubDomains"))
        .layer(set("cross-origin-opener-policy", "same-origin"))
}

