// src/health.rs - route: .route("/api/health", get(health::health))
use std::time::Duration;

use axum::{
    extract::State,
    http::{header, StatusCode},
    response::{IntoResponse, Response},
};

use crate::AppState;

pub async fn health(State(app): State<AppState>) -> Response {
    // OPS-002: process up AND database reachable. Replace the query with your critical dependency's ping.
    let check = sqlx::query("SELECT 1").execute(&app.db);
    let up = matches!(tokio::time::timeout(Duration::from_secs(2), check).await, Ok(Ok(_)));
    // 200 when up, 503 when the check fails or times out. The body never carries versions, hosts or the error.
    let (status, body) = if up {
        (StatusCode::OK, r#"{"status":"ok"}"#)
    } else {
        (StatusCode::SERVICE_UNAVAILABLE, r#"{"status":"unavailable"}"#)
    };
    (status, [(header::CONTENT_TYPE, "application/json"), (header::CACHE_CONTROL, "no-store")], body).into_response()
}

