use crate::{errors::AppError, AppState};

// Indexable public pages only (200, canonical, no noindex). Load these from your CMS or database if dynamic.
const PUBLIC_PATHS: &[&str] = &["/", "/contact", "/privacy"];

pub async fn robots(State(app): State<AppState>) -> Response {
    let body = if app.cfg.production {
        // Disallow only app/API/private paths; never /assets/ (CSS and JS must stay crawlable).
        format!("User-agent: *\nAllow: /\nDisallow: /api/\nDisallow: /contact/thanks\n\nSitemap: {}/sitemap.xml\n", app.cfg.site_url)
    } else {
        "User-agent: *\nDisallow: /\n".to_string() // IDX-005: no Sitemap line outside production
    };
    ([(header::CONTENT_TYPE, "text/plain; charset=utf-8")], body).into_response()
}

pub async fn sitemap(State(app): State<AppState>) -> Response {
    if !app.cfg.production {
        return AppError::NotFound.into_response(); // no sitemap outside production
    }
    // Absolute canonical URLs on the configured origin. Limit: 50,000 URLs per file; above that, add a sitemap index.
    let mut xml = String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");
    for path in PUBLIC_PATHS.iter().take(50_000) {
        xml.push_str(&format!("<url><loc>{}</loc></url>\n", escape(&format!("{}{}", app.cfg.site_url, path))));
    }
    xml.push_str("</urlset>\n");
    ([(header::CONTENT_TYPE, "application/xml; charset=utf-8")], xml).into_response()
}

fn escape(s: &str) -> String {
    s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;").replace('\'', "&apos;")
}

/// IDX-005: every response outside production says noindex; production never sends it.
pub async fn noindex_outside_production(State(app): State<AppState>, req: Request, next: Next) -> Response {
    let mut res = next.run(req).await;
    if !app.cfg.production {
        res.headers_mut().insert("x-robots-tag", HeaderValue::from_static("noindex, nofollow"));
    }
    res
}
